#!/bin/bash
# DevHub/OpenClaw entrypoint for the stock LacledesLAN GoldenEye: Source image.
# Configuration comes only from validated environment variables:
#   GES_MAP            map name (default ge_archives)
#   GES_MAXPLAYERS     1-32 (default 16)
#   GES_HOSTNAME       server browser name (optional)
#   GES_PASSWORD       join password (optional)
#   GES_RCON_PASSWORD  RCON password (optional; empty disables RCON).
#                      27015/TCP must never be published publicly.
# Values are validated against strict allow-lists before they reach srcds
# argv or the generated cfg file, so they cannot inject console commands
# (srcds splits on ';' and newlines) or shell syntax.
set -euo pipefail

readonly GAME_DIR=/app/gesource
readonly CFG_DIR="${GAME_DIR}/cfg"
readonly ENV_CFG="${CFG_DIR}/devhub_env.cfg"
readonly PORT=27015

GES_MAP="${GES_MAP:-ge_archives}"
GES_MAXPLAYERS="${GES_MAXPLAYERS:-16}"
GES_HOSTNAME="${GES_HOSTNAME:-GoldenEye: Source}"
GES_PASSWORD="${GES_PASSWORD:-}"
GES_RCON_PASSWORD="${GES_RCON_PASSWORD:-}"

fail() { echo "devhub-entrypoint: $*" >&2; exit 64; }

# Error messages name keys only and never echo submitted values.
[[ "$GES_MAP" =~ ^[A-Za-z0-9_]{1,64}$ ]] || fail "GES_MAP must be 1-64 letters, numbers or _."
[[ -f "${GAME_DIR}/maps/${GES_MAP}.bsp" ]] || fail "GES_MAP does not name an installed map."
[[ "$GES_MAXPLAYERS" =~ ^[0-9]{1,2}$ ]] && (( 10#$GES_MAXPLAYERS >= 1 && 10#$GES_MAXPLAYERS <= 32 )) || fail "GES_MAXPLAYERS must be a whole number from 1 to 32."
GES_MAXPLAYERS=$((10#$GES_MAXPLAYERS))
readonly HOST_RE="^[][A-Za-z0-9 _.,:!#@&'+/()-]{1,63}$"
[[ "$GES_HOSTNAME" =~ $HOST_RE ]] || fail "GES_HOSTNAME must be 1-63 characters without quotes, semicolons, backslashes, \$ or backticks."
readonly SECRET_RE='^[A-Za-z0-9_.!@#%^*+=,:~/-]{1,64}$'
if [[ -n "$GES_PASSWORD" ]]; then [[ "$GES_PASSWORD" =~ $SECRET_RE ]] || fail "GES_PASSWORD must be 1-64 characters without spaces, quotes, semicolons, backslashes, \$ or backticks."; fi
if [[ -n "$GES_RCON_PASSWORD" ]]; then [[ "$GES_RCON_PASSWORD" =~ $SECRET_RE ]] || fail "GES_RCON_PASSWORD must be 1-64 characters without spaces, quotes, semicolons, backslashes, \$ or backticks."; fi

# server.cfg runs on every map load; chain our generated cfg at its end so
# these values override the stock hostname without editing upstream lines.
umask 077
{
  echo "// Generated by devhub-entrypoint.sh at container start. Do not edit."
  echo "hostname \"${GES_HOSTNAME}\""
  echo "sv_password \"${GES_PASSWORD}\""
  echo "rcon_password \"${GES_RCON_PASSWORD}\""
} > "$ENV_CFG"
touch "${CFG_DIR}/server.cfg"
grep -qx 'exec devhub_env.cfg' "${CFG_DIR}/server.cfg" || printf '\nexec devhub_env.cfg\n' >> "${CFG_DIR}/server.cfg"
unset GES_PASSWORD GES_RCON_PASSWORD

cd /app
exec /app/srcds_run -game gesource -norestart -port "$PORT" +maxplayers "$GES_MAXPLAYERS" +map "$GES_MAP" "$@"
